import {bookState,bookPart,setBookPage,grammarBook,grammarExercises,grammarItemMap,writeBookAnswer,submitBookAnswer,bookMistakes} from './grammar-reader-model.js';
import {syncNow,accountState,subscribe} from './account-store.js';
import {captureBookPage,cancelBookTurn,prepareBookSound,turnBookPage} from './grammar-page-turn.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let getState,save,notify,pdfjs,documentPromise,partFile,renderTask,generation=0,scrollTimer;
const pageGroups=page=>grammarExercises.filter(g=>(g.pages||[g.page]).includes(page));
const pageItems=(g,page)=>g.items.filter(q=>!q.page||q.page===page);
const button=(action,label,attrs='')=>`<button type="button" data-book="${action}" ${attrs}>${label}</button>`;
const checkTime=at=>at?new Date(at).toLocaleString('zh-CN',{hour12:false}):'更新前记录（时间未记录）';
function history(id){const r=bookState(getState()).exercises[id],attempts=r?.attempts||[],wrong=bookMistakes(r);if(!attempts.length)return '';
 const last=attempts.at(-1),lastWrong=wrong.at(-1);
 return `<div class="book-check-history">${lastWrong?`<div class="book-mistake-reminder"><strong>${r.result==='correct'?'曾答错 · 本次已订正':'错题提醒'} · 累计 ${wrong.length} 次</strong><p>上次错答：<span lang="en">${h(lastWrong.answer)}</span></p><time>${h(checkTime(lastWrong.at))}</time></div>`:''}${!r.result?`<p class="book-unchecked">当前内容尚未检查。上次提交：<span lang="en">${h(last.answer)}</span></p>`:''}<details><summary>检查记录 · ${attempts.length} 次</summary><ol>${[...attempts].reverse().map(a=>`<li class="${a.result}"><div><b>${{correct:'正确',incorrect:'当时答错',self:'参考对照'}[a.result]}</b><time>${h(checkTime(a.at))}</time></div><p lang="en">${h(a.answer)}</p>${a.reference?`<p class="book-history-reference">当时参考：${h(a.reference)}</p>`:''}</li>`).join('')}</ol></details></div>`;
}
function feedback(id){const r=bookState(getState()).exercises[id],q=grammarItemMap[id];
 return (r?.result?`<div class="book-feedback ${r.result}" role="status"><strong>${{correct:'✓ 正确',incorrect:'再检查一下',self:'请对照参考答案'}[r.result]}</strong><p>参考：<span lang="en">${h(q.answer)}</span>${q.alternatives?.length?`<br><small>也可：${q.alternatives.map(h).join(' / ')}</small>`:''}</p>${r.result==='self'?`<label><input type="checkbox" data-book-self="${h(id)}" ${r.selfChecked?'checked':''}> 我已对照参考答案</label>`:''}</div>`:'')+history(id);
}
function exercises(page){const groups=pageGroups(page),unit=grammarBook.units.find(u=>u.page===page||u.exercisePage===page);
 if(!groups.length)return `<div class="book-exercise-empty"><span class="mini-label">${unit?'UNIT '+unit.unit:'教材阅读'}</span><h2>${unit?'先理解，再练习':'跟随自己的节奏阅读'}</h2><p>点击页角或左右滑动翻页，方向键也可翻页。阅读位置会自动保存。</p>${unit?button('page','打开本单元练习 →',`data-page="${unit.exercisePage}"`):''}</div>`;
 return `<div class="book-exercise-heading"><span class="mini-label">${unit?'UNIT '+unit.unit:'ADDITIONAL EXERCISES'}</span><h2>边读边练</h2><p>题目见左侧原书。多空答案按顺序用 <b>|</b> 分隔；开放题填写后对照参考。</p>${unit?button('page','← 回看讲解',`data-page="${unit.page}"`):''}</div>${groups.map(g=>`<section class="book-group"><div class="book-group-heading"><h3>练习 ${h(g.id)}</h3>${button('page','书后答案',`data-page="${g.keyPages[0]}"`)}</div><p class="book-instruction">${h(g.instruction||'根据书中的题目填写答案。')}</p>${pageItems(g,page).map(q=>{const id=g.id+':'+q.id,r=bookState(getState()).exercises[id];return `<div class="book-item ${r?.result==='incorrect'?'is-incorrect':bookMistakes(r).length?'was-incorrect':''}" data-book-item="${h(id)}"><label for="book-answer-${h(id)}">${h(q.label||q.id)}${(q.mode||g.mode)==='self'?'<small> · 自行对照</small>':''}</label><div class="book-answer-row"><textarea rows="2" id="book-answer-${h(id)}" data-book-answer="${h(id)}" maxlength="2000" spellcheck="false" autocomplete="off" aria-invalid="${r?.result==='incorrect'}" aria-label="练习 ${h(g.id)} 第 ${h(q.label||q.id)} 题">${h(r?.draft||'')}</textarea>${button('check','检查',`data-item="${h(id)}"`)}</div><div data-book-feedback="${h(id)}">${feedback(id)}</div></div>`;}).join('')}${button('check-group','检查本组已填答案',`data-group="${h(g.id)}"`)}</section>`).join('')}`;
}
export function bookReaderPage(state){const b=bookState(state);queueMicrotask(()=>{updateSaveStatus();mountPage();});return `<section class="book-reader" aria-label="Essential Grammar in Use 阅读器"><div class="book-title"><div><div class="eyebrow">READ · PRACTISE · RETURN</div><h1>Essential Grammar in Use</h1><p>完整教材 · 115 个单元 · 阅读与练习进度随账号保存</p></div><span id="book-save-status" role="status"></span></div><div class="book-controls"><label>单元 <select id="book-unit" aria-label="选择教材单元"><option value="">选择单元</option>${grammarBook.units.map(u=>`<option value="${u.page}" ${[u.page,u.exercisePage].includes(b.page)?'selected':''}>${u.unit}. ${h(u.title)}</option>`).join('')}</select></label><label>目录 <select id="book-section" aria-label="教材目录"><option value="">跳转章节</option>${grammarBook.sections.map(s=>`<option value="${s.page}">${h(s.title)}</option>`).join('')}</select></label><label>缩放 <select id="book-zoom">${[.75,1,1.25,1.5,2].map(z=>`<option value="${z}" ${b.zoom===z?'selected':''}>${Math.round(z*100)}%</option>`).join('')}</select></label>${button('sound','翻页音效：'+(b.sound!==false?'开':'关'),`id="book-sound" aria-pressed="${b.sound!==false}"`)}</div><div class="book-layout"><section class="book-paper"><div class="book-pagination">${button('previous','← 上一页')}<form id="book-jump"><label>PDF 页 <input id="book-page" type="number" min="1" max="${grammarBook.pages}" value="${b.page}" aria-label="PDF 页码"> / ${grammarBook.pages}</label><button type="submit">前往</button></form>${button('next','下一页 →')}</div><div id="book-viewport" tabindex="0" aria-label="教材页面，可滚动阅读"><p id="book-loading" role="status">正在载入教材…</p><div id="book-sheet"><canvas id="book-canvas" aria-label="教材 PDF 页面"></canvas>${button('edge-previous','‹','class="book-corner previous" aria-label="从页角翻到上一页"')}${button('edge-next','›','class="book-corner next" aria-label="从页角翻到下一页"')}</div></div><div class="book-page-footer"><span id="book-page-label"></span><a id="book-native" target="_blank" rel="noopener">打开 PDF 原页 ↗</a></div></section><aside id="book-exercises" aria-label="本页练习">${exercises(b.page)}</aside></div></section>`;}
async function mountPage(previous=null){const canvas=document.querySelector('#book-canvas');if(!canvas)return;const token=++generation,b=bookState(getState()),page=b.page,part=bookPart(page),viewport=document.querySelector('#book-viewport'),loading=document.querySelector('#book-loading'),sheet=document.querySelector('#book-sheet');
 clearTimeout(scrollTimer);viewport.onscroll=null;renderTask?.cancel();renderTask=null;cancelBookTurn();canvas.dataset.ready='false';viewport.setAttribute('aria-busy','true');
 document.querySelector('#book-page').value=page;document.querySelector('#book-page-label').textContent=`PDF 第 ${page} 页 · 共 ${grammarBook.pages} 页`;
 document.querySelector('#book-native').href=`/grammar-book/${part.file}#page=${page-part.start+1}`;
 document.querySelector('[data-book="previous"]').disabled=page===1;document.querySelector('[data-book="next"]').disabled=page===grammarBook.pages;
 document.querySelector('[data-book="edge-previous"]').disabled=page===1;document.querySelector('[data-book="edge-next"]').disabled=page===grammarBook.pages;
 document.querySelector('#book-unit').value=String(grammarBook.units.find(u=>[u.page,u.exercisePage].includes(page))?.page||'');
 loading.hidden=false;loading.textContent='正在载入教材…';sheet.classList.toggle('has-page',!!canvas.dataset.page);viewport.classList.toggle('can-swipe',b.zoom<=1);const savedScroll={...b.scroll};
 try{pdfjs??=await import('./vendor/pdfjs/pdf.min.js');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdfjs/pdf.worker.min.js';
  if(partFile!==part.file){const old=documentPromise;partFile=part.file;documentPromise=pdfjs.getDocument({url:`/grammar-book/${part.file}`,cMapUrl:'/vendor/pdfjs/cmaps/',cMapPacked:true,standardFontDataUrl:'/vendor/pdfjs/standard_fonts/',wasmUrl:'/vendor/pdfjs/wasm/',isEvalSupported:false}).promise;old?.then(doc=>doc.destroy()).catch(()=>{});}
  const doc=await documentPromise;if(token!==generation||!canvas.isConnected)return;const pdfPage=await doc.getPage(page-part.start+1);if(token!==generation||!canvas.isConnected)return;
  const size=pdfPage.getViewport({scale:1}),width=Math.max(240,viewport.clientWidth-24),scale=width/size.width*b.zoom,view=pdfPage.getViewport({scale}),ratio=Math.min(window.devicePixelRatio||1,2);
  const rendered=document.createElement('canvas');rendered.width=Math.floor(view.width*ratio);rendered.height=Math.floor(view.height*ratio);
  renderTask=pdfPage.render({canvasContext:rendered.getContext('2d'),viewport:view,transform:ratio!==1?[ratio,0,0,ratio,0,0]:null});await renderTask.promise;if(token!==generation||!canvas.isConnected)return;
  canvas.width=rendered.width;canvas.height=rendered.height;canvas.style.width=view.width+'px';canvas.style.height=view.height+'px';canvas.getContext('2d').drawImage(rendered,0,0);canvas.dataset.renderedPage=String(page);sheet.style.width=view.width+'px';sheet.classList.add('has-page');
  loading.hidden=true;canvas.hidden=false;canvas.setAttribute('aria-label',`Essential Grammar in Use，PDF 第 ${page} 页`);
  viewport.scrollLeft=savedScroll.x*Math.max(0,viewport.scrollWidth-viewport.clientWidth);viewport.scrollTop=savedScroll.y*Math.max(0,viewport.scrollHeight-viewport.clientHeight);
  if(previous&&previous.page!==page)await turnBookPage(sheet,canvas,previous,{sound:b.sound!==false});if(token!==generation||!canvas.isConnected)return;canvas.dataset.page=String(page);canvas.dataset.ready='true';viewport.setAttribute('aria-busy','false');
  viewport.onscroll=()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{if(token!==generation)return;b.scroll={x:viewport.scrollLeft/Math.max(1,viewport.scrollWidth-viewport.clientWidth),y:viewport.scrollTop/Math.max(1,viewport.scrollHeight-viewport.clientHeight)};save();},180);};
 }catch(error){if(token!==generation||error.name==='RenderingCancelledException')return;documentPromise=null;partFile=null;viewport.setAttribute('aria-busy','false');loading.hidden=false;loading.textContent='教材暂时未能载入，请点击“重试”，或打开 PDF 原页。';const retry=document.createElement('button');retry.textContent='重试';retry.onclick=()=>mountPage(captureBookPage(canvas));loading.append(' ',retry);}
}
function updateSaveStatus(){const el=document.querySelector('#book-save-status');if(!el)return;const a=accountState();el.textContent=a.user?(a.pending.includes('grammar')?'已存本机 · '+a.status:'已同步到账号'):'访客 · 已保存到本机';}
function persist(){if(save()){updateSaveStatus();void syncNow().then(updateSaveStatus);}}
function navigate(page){const b=bookState(getState());if(page===b.page)return;clearTimeout(scrollTimer);setBookPage(getState(),page);prepareBookSound(b.sound!==false);cancelBookTurn();const previous=captureBookPage(document.querySelector('#book-canvas'));persist();document.querySelector('#book-exercises').innerHTML=exercises(page);void mountPage(previous);}
function updateFeedback(id){const el=[...document.querySelectorAll('[data-book-feedback]')].find(el=>el.dataset.bookFeedback===id);if(!el)return;el.innerHTML=feedback(id);const r=bookState(getState()).exercises[id],item=el.closest('.book-item');item.classList.toggle('is-incorrect',r?.result==='incorrect');item.classList.toggle('was-incorrect',r?.result!=='incorrect'&&bookMistakes(r).length>0);item.querySelector('textarea').setAttribute('aria-invalid',String(r?.result==='incorrect'));}
export function initBookReader(options){getState=options.getState;save=options.save;notify=options.toast;
 subscribe(updateSaveStatus);
 document.addEventListener('click',e=>{const b=e.target.closest('[data-book]');if(!b||b.disabled)return;try{const state=getState(),book=bookState(state);switch(b.dataset.book){case'edge-previous':case'previous':navigate(book.page-1);break;case'edge-next':case'next':navigate(book.page+1);break;case'page':navigate(Number(b.dataset.page));break;case'sound':book.sound=book.sound===false;prepareBookSound(book.sound);b.textContent='翻页音效：'+(book.sound?'开':'关');b.setAttribute('aria-pressed',String(book.sound));persist();break;case'check':submitBookAnswer(state,b.dataset.item);updateFeedback(b.dataset.item);persist();break;case'check-group':{const group=pageGroups(book.page).find(g=>g.id===b.dataset.group),at=new Date().toISOString();let count=0;for(const item of pageItems(group,book.page)){const id=group.id+':'+item.id;if(book.exercises[id]?.draft.trim()){submitBookAnswer(state,id,at);updateFeedback(id);count++;}}if(!count)notify('请先填写答案。');else persist();break;}}}catch(err){notify(err.message);}});
 document.addEventListener('submit',e=>{if(e.target.id==='book-jump'){e.preventDefault();try{navigate(Number(document.querySelector('#book-page').value));}catch(err){notify(err.message);}}});
 document.addEventListener('input',e=>{const id=e.target.dataset.bookAnswer;if(id){try{writeBookAnswer(getState(),id,e.target.value);updateFeedback(id);save();}catch(err){notify(err.message);}}});
 document.addEventListener('change',e=>{try{if(['book-unit','book-section'].includes(e.target.id)&&e.target.value)navigate(Number(e.target.value));if(e.target.id==='book-section')e.target.value='';if(e.target.id==='book-zoom'){bookState(getState()).zoom=Number(e.target.value);persist();void mountPage();}if(e.target.dataset.bookSelf){const r=bookState(getState()).exercises[e.target.dataset.bookSelf];if(r?.result==='self'){r.selfChecked=e.target.checked;persist();}}if(e.target.dataset.bookAnswer)persist();}catch(err){notify(err.message);}});
 document.addEventListener('keydown',e=>{if(e.target.id!=='book-viewport'||e.altKey||e.ctrlKey||e.metaKey||!['ArrowLeft','ArrowRight','PageUp','PageDown'].includes(e.key))return;e.preventDefault();const b=bookState(getState()),next=b.page+(['ArrowRight','PageDown'].includes(e.key)?1:-1);if(next>=1&&next<=grammarBook.pages)navigate(next);});
 let swipe=null,resizeTimer;
 document.addEventListener('pointerdown',e=>{if(e.isPrimary&&e.target.closest('#book-viewport')&&!e.target.closest('button')&&bookState(getState()).zoom<=1)swipe={x:e.clientX,y:e.clientY,pointer:e.pointerId};});
 document.addEventListener('pointercancel',()=>{swipe=null;});
 document.addEventListener('pointerup',e=>{const start=swipe;swipe=null;if(!start||start.pointer!==e.pointerId||!e.target.closest('#book-viewport'))return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.5)return;const next=bookState(getState()).page+(dx<0?1:-1);if(next>=1&&next<=grammarBook.pages)navigate(next);});
 window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(document.querySelector('#book-canvas'))void mountPage();},180);});
 window.addEventListener('hashchange',()=>{if(location.hash!=='#grammar'){generation++;clearTimeout(scrollTimer);renderTask?.cancel();cancelBookTurn();}});
}
